            if (campaignUpdateRequest.IsFlexibleDailyBudgetsOption.IsSet)
                if (campaignUpdateRequest.IsFlexibleDailyBudgetsOption.Value != null)
                    writer.WriteBoolean("is_flexible_daily_budgets", campaignUpdateRequest.IsFlexibleDailyBudgetsOption.Value!.Value);
                else
                    writer.WriteNull("is_flexible_daily_budgets");

            if (campaignUpdateRequest.DefaultAdGroupBudgetInMicroCurrencyOption.IsSet)
                if (campaignUpdateRequest.DefaultAdGroupBudgetInMicroCurrencyOption.Value != null)
                    writer.WriteNumber("default_ad_group_budget_in_micro_currency", campaignUpdateRequest.DefaultAdGroupBudgetInMicroCurrencyOption.Value!.Value);
                else
                    writer.WriteNull("default_ad_group_budget_in_micro_currency");

            if (campaignUpdateRequest.IsAutomatedCampaignOption.IsSet)
                if (campaignUpdateRequest.IsAutomatedCampaignOption.Value != null)
                    writer.WriteBoolean("is_automated_campaign", campaignUpdateRequest.IsAutomatedCampaignOption.Value!.Value);
                else
                    writer.WriteNull("is_automated_campaign");

            if (campaignUpdateRequest.IsCampaignBudgetOptimizationOption.IsSet)
                if (campaignUpdateRequest.IsCampaignBudgetOptimizationOption.Value != null)
                    writer.WriteBoolean("is_campaign_budget_optimization", campaignUpdateRequest.IsCampaignBudgetOptimizationOption.Value!.Value);
                else
                    writer.WriteNull("is_campaign_budget_optimization");

            if (campaignUpdateRequest.ObjectiveTypeOption.IsSet)
                if (campaignUpdateRequest.ObjectiveTypeOption!.Value != null)
                {
                    var objectiveTypeRawValue = ObjectiveTypeValueConverter.ToJsonValue(campaignUpdateRequest.ObjectiveTypeOption.Value!.Value);
                    writer.WriteString("objective_type", objectiveTypeRawValue);
                }
                else
                    writer.WriteNull("objective_type");
        }
    }
}
